insert into public.study_series (
  id, study_path_id, slug, title, description, short_description, long_description,
  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-000000000075',
  'b1000001-0000-4000-8000-000000000001',
  'the-promise-kept',
  'The Promise Kept',
  'After humanity fell, God did not abandon the world to sin, shame, and death. He gave the first gospel promise: a coming Deliverer would defeat the enemy and rescue humanity.' || E'\n\n' ||
  'This study traces that promise from Eden to the cross. It shows how the Old Testament points forward to Jesus, how Daniel''s 70-week timeline foretold the Messiah''s mission, and how Christ fulfilled God''s promise of faithful love through His life, death, and resurrection.' || E'\n\n' ||
  'The story of Scripture is not God giving up on humanity. It is God keeping His promise at great cost to Himself.',
  'Follow God''s promise of redemption from Eden to Christ.',
  'After humanity fell, God did not abandon the world to sin, shame, and death. He gave the first gospel promise: a coming Deliverer would defeat the enemy and rescue humanity.' || E'\n\n' ||
  'This study traces that promise from Eden to the cross. It shows how the Old Testament points forward to Jesus, how Daniel''s 70-week timeline foretold the Messiah''s mission, and how Christ fulfilled God''s promise of faithful love through His life, death, and resurrection.' || E'\n\n' ||
  'The story of Scripture is not God giving up on humanity. It is God keeping His promise at great cost to Himself.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  7
);

insert into public.study_series (
  id, study_path_id, slug, title, description, short_description, long_description,
  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-000000000076',
  'b1000001-0000-4000-8000-000000000001',
  'the-way-back-to-god',
  'The Way Back to God',
  'Sin separated humanity from God, but Scripture shows that God has made a way back. The sanctuary was more than an ancient religious structure. It was a living map of salvation.' || E'\n\n' ||
  'Through its spaces, symbols, sacrifices, priestly ministry, and Day of Atonement, the sanctuary pointed forward to Jesus. He is the Door, the Lamb, the Bread of Life, the Light of the world, our Intercessor, our High Priest, and the One who writes God''s law of love in our hearts.' || E'\n\n' ||
  'This study helps beginners understand the sanctuary as a Christ-centered journey from separation to restoration.',
  'Learn how God restores sinners through grace, repentance, and trust.',
  'Sin separated humanity from God, but Scripture shows that God has made a way back. The sanctuary was more than an ancient religious structure. It was a living map of salvation.' || E'\n\n' ||
  'Through its spaces, symbols, sacrifices, priestly ministry, and Day of Atonement, the sanctuary pointed forward to Jesus. He is the Door, the Lamb, the Bread of Life, the Light of the world, our Intercessor, our High Priest, and the One who writes God''s law of love in our hearts.' || E'\n\n' ||
  'This study helps beginners understand the sanctuary as a Christ-centered journey from separation to restoration.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  8
);

insert into public.study_series (
