) values (
  'e4000001-0000-4000-8000-000000000077',
  'b1000001-0000-4000-8000-000000000001',
  'what-happens-when-we-die',
  'What Happens When We Die?',
  'Death raises one of life''s deepest questions: what happens when we die?' || E'\n\n' ||
  'This study explores the Bible''s teaching on the first death, the unconscious sleep of the dead, the resurrection, and the second death. It also shows why Scripture warns against attempts to communicate with the dead and why our hope is not found in fear, speculation, or superstition, but in Jesus.' || E'\n\n' ||
  'Most importantly, this study reveals that Christ tasted death for everyone, conquered the power of guilt, and offers complete forgiveness, resurrection hope, and eternal life to all who trust Him.',
  'Study what Scripture teaches about death, sleep, resurrection, and hope.',
  'Death raises one of life''s deepest questions: what happens when we die?' || E'\n\n' ||
  'This study explores the Bible''s teaching on the first death, the unconscious sleep of the dead, the resurrection, and the second death. It also shows why Scripture warns against attempts to communicate with the dead and why our hope is not found in fear, speculation, or superstition, but in Jesus.' || E'\n\n' ||
  'Most importantly, this study reveals that Christ tasted death for everyone, conquered the power of guilt, and offers complete forgiveness, resurrection hope, and eternal life to all who trust Him.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  9
);

