insert into public.study_series (
  id, study_path_id, slug, title, description, short_description, long_description,
  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-00000000007b',
  'b1000001-0000-4000-8000-000000000001',
  'the-rest-god-gives',
  'The Rest God Gives',
  'The Rest God Gives explores the Sabbath as a weekly reminder of creation, redemption, grace, and restored relationship with God.' || E'\n\n' ||
  'This study shows that Sabbath rest is not about earning God''s favor. It is a sign that we receive life and salvation as gifts from Him. From Genesis to the life of Jesus and the New Testament church, Scripture presents the Sabbath as a sacred space in time where humanity is invited to rest in God''s completed work.' || E'\n\n' ||
  'The Sabbath teaches us to stop striving, remember our Creator, trust our Redeemer, and receive the deeper rest Christ gives to the soul.',
  'Explore the gift of Sabbath rest and what it reveals about trust in God.',
  'The Rest God Gives explores the Sabbath as a weekly reminder of creation, redemption, grace, and restored relationship with God.' || E'\n\n' ||
  'This study shows that Sabbath rest is not about earning God''s favor. It is a sign that we receive life and salvation as gifts from Him. From Genesis to the life of Jesus and the New Testament church, Scripture presents the Sabbath as a sacred space in time where humanity is invited to rest in God''s completed work.' || E'\n\n' ||
  'The Sabbath teaches us to stop striving, remember our Creator, trust our Redeemer, and receive the deeper rest Christ gives to the soul.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  13
);

insert into public.study_series (
