  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-00000000007c',
  'b1000001-0000-4000-8000-000000000001',
  'the-life-that-gives',
  'The Life That Gives',
  'The Life That Gives explores the biblical principle of generosity as a reflection of God''s own heart.' || E'\n\n' ||
  'God is the Great Giver. Every good gift comes from Him, and the greatest gift is Jesus Christ. In response to His grace, believers are invited into a life of giving, stewardship, tithe, offerings, service, and practical love.' || E'\n\n' ||
  'This study shows that Christian giving is not about religious pressure or self-righteous performance. It is a grace-shaped response to the God who gave first. Through tithes, offerings, generosity, and service, believers participate in God''s circle of blessing for the advancement of the gospel and the relief of human need.',
  'Learn how stewardship, service, and generosity flow from God''s love.',
  'The Life That Gives explores the biblical principle of generosity as a reflection of God''s own heart.' || E'\n\n' ||
  'God is the Great Giver. Every good gift comes from Him, and the greatest gift is Jesus Christ. In response to His grace, believers are invited into a life of giving, stewardship, tithe, offerings, service, and practical love.' || E'\n\n' ||
  'This study shows that Christian giving is not about religious pressure or self-righteous performance. It is a grace-shaped response to the God who gave first. Through tithes, offerings, generosity, and service, believers participate in God''s circle of blessing for the advancement of the gospel and the relief of human need.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  14
);

insert into public.study_series (
  id, study_path_id, slug, title, description, short_description, long_description,
  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-00000000007d',
  'b1000001-0000-4000-8000-000000000001',
  'designed-to-thrive',
  'Designed to Thrive',
  'Designed to Thrive explores the biblical view of health as part of God''s loving design for human flourishing.' || E'\n\n' ||
  'Because God is love, He cares about the whole person: body, mind, heart, and spirit. This study introduces the principle of cause and effect, the meaning of biblical wisdom, and the way daily choices shape well-being.' || E'\n\n' ||
  'Through Scripture, students will see that salvation is not only about future hope, but also about God''s desire to restore, heal, and make us whole. This study also explores the original diet, temperance, health stewardship, and the healing ministry of Jesus.' || E'\n\n' ||
  'Designed to Thrive helps beginners understand that health is not about perfection, pride, or legalism. It is about responding to God''s love by caring for the life He has entrusted to us.',
  'Discover how God''s design touches the whole life, including body, mind, and spirit.',
  'Designed to Thrive explores the biblical view of health as part of God''s loving design for human flourishing.' || E'\n\n' ||
  'Because God is love, He cares about the whole person: body, mind, heart, and spirit. This study introduces the principle of cause and effect, the meaning of biblical wisdom, and the way daily choices shape well-being.' || E'\n\n' ||
  'Through Scripture, students will see that salvation is not only about future hope, but also about God''s desire to restore, heal, and make us whole. This study also explores the original diet, temperance, health stewardship, and the healing ministry of Jesus.' || E'\n\n' ||
  'Designed to Thrive helps beginners understand that health is not about perfection, pride, or legalism. It is about responding to God''s love by caring for the life He has entrusted to us.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  15
);

insert into public.study_series (
  id, study_path_id, slug, title, description, short_description, long_description,
  level, duration_summary, lessons_count, featured, collection_label, sort_order
) values (
  'e4000001-0000-4000-8000-00000000007e',
  'b1000001-0000-4000-8000-000000000001',
  'buried-and-raised',
  'Buried and Raised',
  'Buried and Raised explores the meaning of baptism as a personal response to God''s love and saving work in Jesus Christ.' || E'\n\n' ||
  'This study shows that God does not force transformation. He draws us with everlasting love, invites us into new birth, and calls us to identify with Christ through baptism by immersion. Baptism symbolizes the death of the old life, burial with Christ, and resurrection into a new life shaped by the Holy Spirit.' || E'\n\n' ||
  'Students will discover what it means to be born again, to repent, to receive the Holy Spirit, to be baptized in the name of the Father, Son, and Holy Spirit, and to begin a life of growing discipleship with Jesus.',
  'Understand baptism as a public sign of death to sin and new life in Christ.',
  'Buried and Raised explores the meaning of baptism as a personal response to God''s love and saving work in Jesus Christ.' || E'\n\n' ||
  'This study shows that God does not force transformation. He draws us with everlasting love, invites us into new birth, and calls us to identify with Christ through baptism by immersion. Baptism symbolizes the death of the old life, burial with Christ, and resurrection into a new life shaped by the Holy Spirit.' || E'\n\n' ||
  'Students will discover what it means to be born again, to repent, to receive the Holy Spirit, to be baptized in the name of the Father, Son, and Holy Spirit, and to begin a life of growing discipleship with Jesus.',
  'Beginner',
  'Approx. 55–70 min total',
  7,
  false,
  'Foundational Studies',
  16
);

