  'Hebrews 10:16 · Jeremiah 31:33 · Exodus 25:21 to 22 · Romans 13:10',
  5,
  null
),
(
  'd3000007-0000-4000-8000-000000000860',
  'e4000001-0000-4000-8000-000000000076',
  'the-daily-path-of-grace',
