  8,
  'Matthew 26:36 to 39 · Isaiah 53:4 to 6 · 2 Corinthians 5:21',
  1,
  null
),
(
  'd3000007-0000-4000-8000-000000000881',
  'e4000001-0000-4000-8000-000000000078',
  'the-weight-of-sin',
  'The Weight of Sin',
  'At the cross, Jesus carried sin, guilt, and separation so humanity could be restored.',
  8,
  'Matthew 27:46 · Isaiah 53:10 to 12 · Psalm 88:3 to 12',
  2,
  null
),
(
  'd3000007-0000-4000-8000-000000000882',
  'e4000001-0000-4000-8000-000000000078',
  'he-chose-the-cross',
  'He Chose the Cross',
  'Jesus was not forced into death. He willingly laid down His life because of love.',
  8,
  'John 10:17 to 18 · Matthew 26:53 · Ephesians 3:19',
  3,
  null
),
(
  'd3000007-0000-4000-8000-000000000883',
  'e4000001-0000-4000-8000-000000000078',
  'death-had-no-claim',
