  'Because Jesus was sinless, death had no rightful power to hold Him.',
  8,
  'Acts 2:24 · Romans 6:23 · Romans 8:1 to 4',
  4,
  null
),
(
  'd3000007-0000-4000-8000-000000000884',
  'e4000001-0000-4000-8000-000000000078',
  'the-power-of-death-broken',
  'The Power of Death Broken',
  'Through His death and resurrection, Jesus destroyed the power of death and freed humanity from fear.',
  8,
  'Hebrews 2:9 · Hebrews 2:14 to 15 · 2 Timothy 1:10 · Revelation 1:18',
  5,
  null
),
(
  'd3000007-0000-4000-8000-000000000885',
  'e4000001-0000-4000-8000-000000000078',
  'victory-secured',
  'Victory Secured',
  'The resurrection guarantees eternal life and the future victory over death.',
  9,
  '1 Corinthians 15:51 to 55 · Revelation 20:6 · Revelation 2:11',
  6,
  null
),
(
  'd3000007-0000-4000-8000-000000000886',
  'e4000001-0000-4000-8000-000000000078',
  'live-from-victory',
  'Live From Victory',
  'Because Jesus defeated death, believers can live with confidence, freedom, and hope.',
  8,
  'Romans 8:38 to 39 · 1 John 4:19 · John 11:25 to 26',
  7,
  null
);

insert into public.lessons (
  id, study_series_id, slug, title, summary, duration_minutes, scripture, sort_order, reader_content
) values (
  'd3000007-0000-4000-8000-000000000887',
