  8,
  '1 Corinthians 15:1 to 4 · Romans 3:24 · Ephesians 2:8 to 10',
  1,
  null
),
(
  'd3000007-0000-4000-8000-000000000888',
  'e4000001-0000-4000-8000-000000000079',
  'what-jesus-already-finished',
  'What Jesus Already Finished',
  'Jesus lived, died, rose, and ascended as humanity''s representative, accomplishing salvation before we ever responded.',
  8,
  'Ephesians 1:3 to 7 · Ephesians 2:4 to 6 · 2 Corinthians 5:14 to 15',
  2,
  null
),
(
  'd3000007-0000-4000-8000-000000000889',
  'e4000001-0000-4000-8000-000000000079',
  'the-new-representative',
  'The New Representative',
