  8,
  '1 Corinthians 15:21 to 22 · 1 Corinthians 15:45 to 49 · Romans 5:17 to 19',
  3,
  null
),
(
  'd3000007-0000-4000-8000-000000000890',
  'e4000001-0000-4000-8000-000000000079',
  'all-things-new',
