  'Good works do not earn salvation, but saving grace teaches us how to live in a new way.',
  8,
  'Titus 2:11 to 14 · Ephesians 2:10 · Philippians 2:12 to 13',
  6,
  null
),
(
  'd3000007-0000-4000-8000-000000000893',
  'e4000001-0000-4000-8000-000000000079',
  'living-as-a-new-creation',
