  8,
  'Exodus 20:1 to 17 · Matthew 22:36 to 40 · 1 John 4:8',
  1,
  null
),
(
  'd3000007-0000-4000-8000-000000000895',
  'e4000001-0000-4000-8000-00000000007a',
