  'Humanity is not naturally aligned with God''s law of love and cannot fulfill it on its own.',
  8,
  'Romans 7:12 to 15 · 1 John 3:4 · Romans 13:10',
  2,
  null
),
(
  'd3000007-0000-4000-8000-000000000896',
  'e4000001-0000-4000-8000-00000000007a',
  'why-we-need-a-savior',
