  8,
  'Romans 7:24 to 25 · Romans 5:19 · Isaiah 64:6',
  3,
  null
),
(
  'd3000007-0000-4000-8000-000000000897',
  'e4000001-0000-4000-8000-00000000007a',
  'righteousness-as-a-gift',
  'Righteousness as a Gift',
  'God provides righteousness through Jesus, not as something we earn but as something we receive.',
  8,
  'Romans 3:24 · Romans 5:15 to 17 · Jeremiah 23:6',
  4,
  null
),
(
  'd3000007-0000-4000-8000-000000000898',
  'e4000001-0000-4000-8000-00000000007a',
  'the-new-covenant',
  'The New Covenant',
  'God promises to write His law in our hearts and transform us from the inside out.',
  8,
  'Jeremiah 31:31 to 34 · Hebrews 8:7 to 12 · Romans 7:6',
  5,
  null
