  and study_series_id = 'e4000001-0000-4000-8000-000000000078';

-- When Death Died — Lesson 3: He Chose the Cross (guided reader JSON).
delete from public.lesson_sections
where lesson_id = 'd3000007-0000-4000-8000-000000000882';

update public.lessons
set reader_content = $wdd_l3_reader$
{"openingThought":"Jesus was not trapped by the cross.\n\nThat matters.\n\nHe was not overpowered by Rome.\nHe was not defeated by religious leaders.\nHe was not caught in a plan gone wrong.\n\nJesus chose the cross.\n\nHe saw the cost.\nHe felt the weight.\nHe knew the suffering ahead.\n\nAnd still, He stayed.\n\nThat kind of love is not passive.\n\nIt is deliberate.\n\nJesus laid down His life willingly so humanity could be brought back to God.","scriptureRef":"John 10:18","scriptureQuote":"No man taketh it from me, but I lay it down of myself.","scriptureAfterPrimary":"Jesus was not helpless.\n\nThe cross was not the moment love lost control.\n\nIt was the moment love chose sacrifice.","scriptureSecondaryRef":"John 10:17","scriptureSecondaryQuote":"Therefore doth my Father love me, because I lay down my life, that I might take it again.","scriptureAfterSecondary":"The Father's love rests on the Son's willing surrender.\n\nJesus lays down His life so He might take it again in resurrection victory.","scriptureSupplementBlocks":[{"type":"scripture","reference":"Matthew 26:53","quote":"Thinkest thou that I cannot now pray to my Father, and he shall presently give me more than twelve legions of angels?"},{"type":"scripture","reference":"Ephesians 3:19","quote":"And to know the love of Christ, which passeth knowledge."},{"type":"scripture","reference":"Philippians 2:8","quote":"And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross."}],"teachingPoints":["1. No one took Jesus' life from Him\n\nJesus said plainly, \"No man taketh it from me.\"\n\nThis means the cross was not an accident.\n\nJesus was not helpless.\n\nHe willingly laid down His life.\n\nThe cross was not the moment love lost control.\n\nIt was the moment love chose sacrifice.","2. Jesus had power to escape\n\nIn Matthew 26, Jesus said He could have called more than twelve legions of angels.\n\nHe was not without options.\n\nHe could have ended the suffering.\n\nHe could have stepped away from the cup.\n\nHe could have refused the cross.\n\nBut He did not.\n\nHe stayed because love held Him there.","3. Jesus humbled Himself\n\nPhilippians says Jesus humbled Himself and became obedient unto death.\n\nThe cross shows humility deeper than words.\n\nJesus did not cling to status, comfort, or self-protection.\n\nHe surrendered Himself fully to the Father's will and humanity's rescue.","4. His love passes knowledge\n\nEphesians says the love of Christ passes knowledge.\n\nThat means His love is deeper than we can fully measure.\n\nThe cross reveals a love that is not shallow, sentimental, or temporary.\n\nIt is costly.\n\nIt is faithful.\n\nIt goes all the way."],"wordStudyBeforeStudyInsight":true,"wordStudyStepTitle":"Word Insight","wordStudyStepIntro":"","wordStudy":{"surface":"Lay Down","lemma":"τίθημι","transliteration":"tithēmi","meaning":"To place, set aside, surrender, or give willingly.","strongs":"G5087","reference":"John 10:18","note":"Jesus did not say His life was taken first.\n\nHe said He laid it down.\n\nThis reveals voluntary love.\n\nThe cross was not forced on Jesus. He chose it for our salvation."},"studyInsight":{"title":"Study Insight","placement":"after_teaching","variant":"christ_connection","body":"The voluntary nature of Jesus' death matters because it shows the heart behind the cross.\n\nIf Jesus had been forced, the cross would look like tragedy only.\n\nBut because He chose it, the cross reveals love.\n\nHe chose surrender.\nHe chose humility.\nHe chose suffering.\nHe chose the burden.\nHe chose us.\n\nThis does not make the cross less painful.\n\nIt makes His love more visible.\n\nJesus knew what death would cost, and He still moved forward.\n\nThe nails did not hold Him there first.\n\nLove did."},"studyInsightBlocks":[{"type":"studyVisual","title":"No one took His life","accent":"stone","payload":{"variant":"comparison","leftTitle":"What Jesus could have done","rightTitle":"What Jesus chose","leftItems":["escape","call angels","avoid suffering"],"rightItems":["surrender","sacrifice","love","rescue"]},"footnote":"No one took His life. He laid it down."},{"type":"scriptureChain","title":"He Laid It Down","references":[{"reference":"John 10:17-18"},{"reference":"Matthew 26:53"},{"reference":"Philippians 2:8"},{"reference":"Ephesians 3:19"}]},{"type":"paragraph","text":"Takeaway: Jesus was not forced into death. He willingly laid down His life because of self-giving love."}],"reflectPrompt":"How does it change your view of the cross to know Jesus chose it willingly?\n\nThink about what this reveals about His love, His courage, and His desire to save you.","lifeApplicationStepTitle":"Life Application and Prayer","lifeApplication":"This week, let the willing love of Jesus confront the lie that God is reluctant to save.\n\nJesus did not have to be convinced to love you.\n\nHe chose the cross.\n\nWhen guilt says, \"God does not want me,\" answer with Christ's words:\n\n\"No man taketh it from me, but I lay it down of myself.\"\n\nHis sacrifice was not reluctant.\n\nHis love moved first.\n\nPrayer:\n\nJesus, thank You for choosing the cross. Thank You that no one took Your life from You, but You laid it down in love. Help me trust that You are not reluctant to save me. Teach me to receive Your sacrifice with humility, gratitude, and faith. Amen.","prayer":"","completionSummary":"Jesus was not trapped by death. No one took His life from Him. He chose the cross in love and laid down His life to rescue us.","lessonQuiz":{"eyebrow":"CHECK YOUR UNDERSTANDING","title":"Quick Review","description":"Check your understanding before moving on.","settings":{"quizRequired":false,"passingScore":70,"allowRetake":true},"questions":[{"id":"wdd-l3-q1","prompt":"According to John 10:18, what did Jesus say about His life?","options":["No one takes it from Him, but He lays it down Himself","Rome had full control over Him","He could not choose obedience","He was surprised by the cross"],"correctIndex":0,"explanation":"Jesus said no one takes His life from Him. He willingly lays it down."},{"id":"wdd-l3-q2","prompt":"What did Jesus say He could ask the Father for in Matthew 26:53?","options":["More than twelve legions of angels","A Roman army","A golden throne immediately","A different gospel"],"correctIndex":0,"explanation":"Jesus said He could call more than twelve legions of angels, showing He had power to escape but chose surrender."},{"id":"wdd-l3-q3","prompt":"According to Philippians 2:8, what did Jesus become obedient unto?","options":["Death, even the death of the cross","Personal pride","Human applause","Sinful desire"],"correctIndex":0,"explanation":"Philippians 2:8 says Jesus humbled Himself and became obedient unto death, even the death of the cross."},{"id":"wdd-l3-q4","prompt":"What does Jesus choosing the cross reveal?","options":["His self-giving love","His lack of power","His confusion","His defeat by evil"],"correctIndex":0,"explanation":"Jesus chose the cross willingly, revealing deliberate, self-giving love."},{"id":"wdd-l3-q5","kind":"reflection","prompt":"What does Jesus' willing sacrifice tell you about how much He wants to save you?","explanation":"The cross shows that Jesus was not reluctant. He laid down His life freely because of love."}]}}
$wdd_l3_reader$::jsonb
where slug = 'he-chose-the-cross'
  and study_series_id = 'e4000001-0000-4000-8000-000000000078';

-- When Death Died — Lesson 4: Death Had No Claim (guided reader JSON).
delete from public.lesson_sections
where lesson_id = 'd3000007-0000-4000-8000-000000000883';

update public.lessons
set reader_content = $wdd_l4_reader$
{"openingThought":"Death had power over humanity because of sin.\n\nBut Jesus had no sin.\n\nThat changes everything.\n\nHe entered death carrying the sins of the world, but death had no rightful claim over Him. He bore sin without becoming sinful. He carried guilt without yielding to rebellion. He stepped into the grave, but the grave could not keep Him.\n\nDeath met the only Person it had no legal right to hold.\n\nThat is why the resurrection was not just surprising.\n\nIt was necessary.","scriptureRef":"Acts 2:24","scriptureQuote":"Whom God hath raised up, having loosed the pains of death: because it was not possible that he should be holden of it.","scriptureAfterPrimary":"This is a massive statement.\n\nDeath held every other human being because all had sinned.\n\nBut Jesus was sinless.\n\nThe grave could not keep the Lord of life.","scriptureSecondaryRef":"Romans 6:23","scriptureSecondaryQuote":"For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.","scriptureAfterSecondary":"Death is connected to sin.\n\nSin disconnects from the Source of life.\n\nThat is why death has power over fallen humanity.","scriptureSupplementBlocks":[{"type":"scripture","reference":"Romans 8:1","quote":"There is therefore now no condemnation to them which are in Christ Jesus."},{"type":"scripture","reference":"Romans 8:3","quote":"For what the law could not do, in that it was weak through the flesh, God sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh."}],"teachingPoints":["1. Death is connected to sin\n\nRomans 6:23 says the wages of sin is death.\n\nDeath is not random.\n\nIt is the result of separation from God, who is life.\n\nSin produces death because sin disconnects from the Source of life.\n\nThat is why death has power over fallen humanity.","2. Jesus had no sin of His own\n\nJesus entered human flesh, but He never yielded to sin.\n\nHe was tempted.\nHe suffered.\nHe felt pressure.\nHe faced darkness.\n\nBut He never rebelled against the Father.\n\nHe carried sin as our substitute, but sin never became His character.","3. Death could not hold Him\n\nActs 2:24 says it was not possible for death to hold Jesus.\n\nDeath held every other human being because all had sinned.\n\nBut Jesus was sinless.\n\nDeath had no rightful claim over Him.\n\nThe grave could not keep the Lord of life.","4. Jesus condemned sin in the flesh\n\nRomans 8 says God condemned sin in the flesh through His Son.\n\nJesus did not merely escape death.\n\nHe defeated the power behind it.\n\nHe entered the human condition, overcame sin from within human life, and broke condemnation for those who are in Him."],"wordStudyBeforeStudyInsight":true,"wordStudyStepTitle":"Word Insight","wordStudyStepIntro":"","wordStudy":{"surface":"Claim","lemma":"κατέχω","transliteration":"katecho","meaning":"A right, demand, or legal hold over something or someone.","strongs":"G2722","reference":"Acts 2:24","note":"Death had a claim over humanity because of sin.\n\nBut death had no claim over Jesus.\n\nHe carried our sin without becoming sinful, and His resurrection proves that death's power was broken."},"studyInsight":{"title":"Study Insight","placement":"after_teaching","variant":"christ_connection","body":"The resurrection was not only a miracle of power.\n\nIt was a declaration of victory.\n\nJesus entered death with our sins upon Him, but He was personally sinless.\n\nDeath could not accuse Him.\nDeath could not own Him.\nDeath could not keep Him.\n\nWhen God raised Jesus, He was showing that sin had been defeated and death had lost its grip.\n\nThis is why Romans 8 begins with such strong hope:\n\n\"There is therefore now no condemnation to them which are in Christ Jesus.\"\n\nJesus broke the claim of death so condemnation would not have the final word over those who trust Him."},"studyInsightBlocks":[{"type":"studyVisual","title":"Death had no rightful claim","accent":"stone","payload":{"variant":"comparison","leftTitle":"Death's claim","rightTitle":"Christ's victory","leftItems":["Sin brings death"],"rightItems":["Jesus bore sin","Remained sinless","Rose again"]},"footnote":"Death had no rightful claim over Him."},{"type":"scriptureChain","title":"Death Could Not Hold Him","references":[{"reference":"Acts 2:24"},{"reference":"Romans 6:23"},{"reference":"Romans 8:1-4"},{"reference":"1 Peter 2:22"}]},{"type":"paragraph","text":"Takeaway: Jesus was sinless, bore sin as our substitute, and rose because death had no rightful claim over Him."}],"reflectPrompt":"How does it change your view of salvation to know Jesus broke death's claim, not just your fear of death?\n\nThink about guilt, condemnation, sin, and the confidence believers can have in Christ.","lifeApplicationStepTitle":"Life Application and Prayer","lifeApplication":"This week, when condemnation speaks, answer it with the resurrection.\n\nCondemnation says:\n\n\"You are still owned by your failure.\"\n\nThe resurrection says:\n\n\"Death could not hold Christ, and condemnation does not get the final word over those in Him.\"\n\nDo not build confidence on your record.\n\nBuild it on Jesus.\n\nHe carried sin.\nHe defeated death.\nHe rose in victory.\n\nPrayer:\n\nJesus, thank You that death had no claim over You. Thank You for bearing sin without becoming sinful and for rising in victory. Help me stop living under condemnation and start trusting what You have done. Anchor my confidence in Your resurrection, not in my performance. Amen.","prayer":"","completionSummary":"Death had no rightful claim over Jesus. He bore sin, remained sinless, and rose again, breaking condemnation for all who are in Him.","lessonQuiz":{"eyebrow":"CHECK YOUR UNDERSTANDING","title":"Quick Review","description":"Check your understanding before moving on.","settings":{"quizRequired":false,"passingScore":70,"allowRetake":true},"questions":[{"id":"wdd-l4-q1","prompt":"According to Acts 2:24, why was death unable to hold Jesus?","options":["It was not possible that He should be held by it","The disciples hid His body","Rome changed its mind","Jesus only appeared to die"],"correctIndex":0,"explanation":"Acts 2:24 says God raised Jesus because it was not possible for death to hold Him."},{"id":"wdd-l4-q2","prompt":"According to Romans 6:23, what are the wages of sin?","options":["Death","Eternal life","Popularity","Wisdom"],"correctIndex":0,"explanation":"Romans 6:23 says the wages of sin is death, showing the connection between sin and death."},{"id":"wdd-l4-q3","prompt":"What does Romans 8:1 say about those who are in Christ Jesus?","options":["There is no condemnation","There is no hope","They are still owned by death","They must save themselves"],"correctIndex":0,"explanation":"Romans 8:1 says there is now no condemnation to those who are in Christ Jesus."},{"id":"wdd-l4-q4","prompt":"What did Jesus do according to Romans 8:3?","options":["Condemned sin in the flesh","Became sinful in character","Avoided human suffering","Denied the Father"],"correctIndex":0,"explanation":"Romans 8:3 says God condemned sin in the flesh through His Son."},{"id":"wdd-l4-q5","kind":"reflection","prompt":"Where do you need to believe that condemnation does not have the final word over you?","explanation":"Jesus broke death's claim through His sinless life, sacrificial death, and victorious resurrection."}]}}
$wdd_l4_reader$::jsonb
